// ---------------- VOLIBEAR, the Relentless Storm ----------------
const VOLPX = PixelArt.make({
  id: 'volibear', win: [-130, -250, 330, 290], B: 1.18, trail: 'rgba(150,230,255,',
  state(v, t) { const S = !!v.transformed; return { S, charged: S || (v.gauge || 0) >= 5, m: pxR(Math.sin(t * 6)) }; },
  body(g, P, s) {
    const S = s.S, { L } = g;
    const fur = S ? ['#5e6878', '#434c5c'] : ['#e2e6ee', '#b8c0cc'], furFar = S ? ['#434c5c', '#2a3140'] : ['#b8c0cc', '#8a92a2'];
    const drawHead = P => {
        const [hx, hy] = P.head;
        for (const [ex, ey] of [[hx - 7, hy - 12], [hx + 3, hy - 15]]) { g.paint([g.ell(ex, ey, 5.5, 5.5)], ...fur); g.fill(g.ell(ex, ey, 2.4, 2.4), S ? '#323a48' : '#a8b0c0'); }
        g.paint([g.ell(hx + 1, hy - 1, 15, 13), g.ell(hx + 14, hy + 4, 10, 7, .1)], ...fur);
        g.fill(g.ell(hx + 14, hy + 5, 8.5, 5.5, .1), S ? '#707a8a' : '#f2f4f8');
        g.fill(g.ell(hx + 23, hy + 1.5, 3, 2.6), '#0a0c10');
        g.fill(g.poly([[hx + 8, hy + 8], [hx + 22, hy + 8], [hx + 18, hy + 13], [hx + 9, hy + 12]]), '#2a0a10');
        for (const f0 of [hx + 11, hx + 18]) g.fill(g.poly([[f0, hy + 8], [f0 + 1.5, hy + 12.5], [f0 + 3, hy + 8]]), '#f8f4e8');
        g.line([[hx + 1, hy - 6], [hx + 12, hy - 3]], '#1a1e28', 2.4);
        g.fill(g.poly([[hx + 4, hy - 1], [hx + 12, hy - 2.5], [hx + 7, hy + 1]]), S ? '#ffffff' : '#bff0ff');
        g.line([[hx - 4, hy - 9], [hx - 1, hy - 3], [hx - 5, hy], [hx - 2, hy + 6]], '#7ad8ff', 1.4);
      };
    g.humanoid(P, {
      limb: 1.5, bulk: 1.65, hips: 1.25, skin: fur, skinFar: furFar, bareArms: true, noHead: true,
      top: S ? ['#4a5466', '#323a48'] : ['#c4cad6', '#98a0b0'], topFar: S ? ['#323a48', '#1e242e'] : ['#98a0b0', '#747c8c'],
      pants: S ? ['#434c5c', '#2a3140'] : ['#b8c0cc', '#8a92a2'], pantsFar: S ? ['#2a3140', '#1a1e28'] : ['#8a92a2', '#6a7282'],
      boots: S ? ['#1a1e28', '#0e1016'] : ['#3a4050', '#262a36'], bootsFar: ['#1a1e28', '#0e1016'],
      belt: S ? ['#7ad8ff', '#3a8ab8'] : ['#3a4a6a', '#2a364e'], bracers: S ? ['#7ad8ff', '#3a8ab8'] : ['#5a6a86', '#3e4a60'],
    }, {
      back(P) { // spiked mane down the back
        const mane = [];
        for (let i = 0; i < 7; i++) { const x = P.sh[0] - 14 + i * 3, y = P.sh[1] - 4 + i * 5, l = (S ? 22 : 16) - i * 1.5; mane.push(g.poly([[x, y], [x - l, y - l * .55 + s.m * 2], [x - 2, y + 6]])); }
        g.paint(mane, S ? '#39424f' : '#eef1f6', S ? '#232a36' : '#a8b0c0');
      },
      chest(P) { const [x, y] = L(P.hip, P.sh, .62); g.line([[x - 8, y - 6], [x - 2, y + 2], [x - 6, y + 8]], S ? '#7ad8ff' : '#6a7488', 1.6); g.line([[x + 6, y - 7], [x + 2, y]], S ? '#7ad8ff' : '#6a7488', 1.6); },
      pads(P) {
        const [sx, sy] = P.sh;
        g.paint([g.poly([[sx - 16, sy + 6], [sx - 12, sy - 8], [sx + 6, sy - 12], [sx + 18, sy - 2], [sx + 14, sy + 8]])], S ? '#2a3240' : '#6a7282', S ? '#1a2028' : '#4a5262');
        g.paint([[-8, 12], [2, 16], [11, 11]].map(([dx, h]) => g.poly([[sx + dx - 3, sy - 8], [sx + dx, sy - 8 - h], [sx + dx + 3, sy - 8]])), '#dff6ff', '#9ab8c8');
        g.line([[sx - 10, sy], [sx - 4, sy - 5], [sx + 2, sy], [sx + 8, sy - 5]], s.charged ? '#9ae6ff' : '#4a88a8', 1.6);
        drawHead(P);
      },
      front(P) { // claws
        const [hx, hy] = P.fH, ang = Math.atan2(P.fH[1] - P.fE[1], P.fH[0] - P.fE[0]);
        for (const off of [-.35, 0, .35]) { const a = ang + off; g.line([[hx + Math.cos(a) * 4, hy + Math.sin(a) * 4], [hx + Math.cos(a) * 14, hy + Math.sin(a) * 14 - 3], [hx + Math.cos(a + .4) * 20, hy + Math.sin(a + .4) * 20]], S ? '#e8f8ff' : '#f4f0e4', 2.8, true); }
      },
    });
  },
  pre(c, v, P, s) { if (s.S) glowCircle(c, 0, -70, 140, 'rgba(120,210,255,0.28)', 'rgba(40,80,160,0)'); },
  post(c, v, P, s) {
    const t = v.anim || 0;
    c.save(); c.globalCompositeOperation = 'lighter';
    glowCircle(c, P.head[0] + 8, P.head[1] - 1, s.S ? 10 : 7, 'rgba(120,220,255,1)', 'rgba(0,0,0,0)');
    c.restore();
    if (s.S) for (let i = 0; i < 2; i++) { const a = t * 7 + i * 3; drawBolt(c, P.sh[0] - 20, P.sh[1] - 20, P.sh[0] - 40 + Math.sin(a) * 18, P.sh[1] - 60 + Math.cos(a) * 12, a, 1.4, '#9ae6ff'); }
    if (s.charged) { const a = t * 11; drawBolt(c, P.fH[0], P.fH[1], P.fH[0] + Math.cos(a) * 30, P.fH[1] + Math.sin(a) * 22, a, 1.2, '#9ae6ff'); }
  },
});

// ---------------- ERIC, the Moonborn (human) and MOONKAI, the Great Ape ----------------
const ERICPX = PixelArt.make({
  id: 'eric', win: [-110, -165, 240, 205], trail: 'rgba(143,211,255,',
  state(v, t) {
    const g = v.gauge || 0, moon = v.side ? !!ericMoon(v) : false;
    return { eyeRed: moon ? .9 : g >= 100 ? .7 : g >= 75 ? .35 : 0, tail: pxR(Math.sin(t * 4), 3), sc1: pxR(Math.sin(t * 9), 3), sc2: pxR(Math.sin(t * 9 + 1), 3) };
  },
  body(g, P, s) {
    const { L } = g;
    g.humanoid(P, {
      limb: 1, bulk: 1, skin: ['#f1c27d', '#d29a5a'], skinFar: ['#d29a5a', '#a87838'], bareArms: false, gloves: true,
      top: ['#2d5fd6', '#1f439c'], topFar: ['#1f439c', '#173478'], pants: ['#2a2a44', '#1c1c30'], pantsFar: ['#1c1c30', '#12121e'],
      boots: ['#6b3416', '#4a2210'], bootsFar: ['#4a2210', '#341808'], belt: ['#e23b3b', '#a82424'], glove: ['#f1c27d', '#d29a5a'], gloveFar: ['#d29a5a', '#a87838'],
    }, {
      back(P) { // the tail he keeps hidden, and the trailing scarf
        const a = [P.hip[0] - 6, P.hip[1] + 4], c1 = [P.hip[0] - 30, P.hip[1] + 10], c2 = [P.hip[0] - 38 + s.tail * 6, P.hip[1] - 14], e = [P.hip[0] - 24 + s.tail * 6, P.hip[1] - 26], pts = [];
        for (let i = 0; i <= 7; i++) { const u = i / 7, w = 1 - u; pts.push([w ** 3 * a[0] + 3 * w * w * u * c1[0] + 3 * w * u * u * c2[0] + u ** 3 * e[0], w ** 3 * a[1] + 3 * w * w * u * c1[1] + 3 * w * u * u * c2[1] + u ** 3 * e[1]]); }
        g.paint(pts.slice(1).map((q, i) => g.cap(pts[i], q, 2.6)), '#6b4226', '#4a2c18');
        const [sx, sy] = P.sh;
        g.paint([g.shape([['M', sx - 2, sy - 2], ['Q', sx - 20, sy + s.sc1 * 5, sx - 34, sy + 6 + s.sc2 * 6], ['L', sx - 30, sy + 12 + s.sc2 * 6], ['Q', sx - 16, sy + 6, sx + 2, sy + 4]])], '#e23b3b', '#a82424');
      },
      chest(P) { g.paint([g.cap([P.sh[0] - 7, P.sh[1] + 2], [P.sh[0] + 7, P.sh[1] + 2], 3)], '#e23b3b', '#a82424'); },
      head(P) {
        const [hx, hy] = P.head, sp = [[-18, -6], [-10, -10], [-16, -18], [-4, -14], [-6, -26], [4, -14], [8, -24], [10, -10], [16, -12], [12, -2]];
        g.paint([g.poly([[hx - 12, hy + 2], ...sp.map(([x, y]) => [hx + x, hy + y]), [hx + 11, hy - 4]])], '#141414', '#0a0a0a');
        g.fill(g.poly([[hx - 8, hy - 15], [hx - 4, hy - 20], [hx - 2, hy - 15]]), '#3a3a52');
        const r = s.eyeRed;
        g.fill(g.ell(hx + 6, hy + 1, 2.2, 2.2), r > 0 ? `rgb(${200 + Math.round(55 * r)},${Math.round(40 * (1 - r))},${Math.round(40 * (1 - r))})` : '#111111');
      },
    });
  },
  pre(c, v, P, s) {
    const g = v.gauge || 0, moon = v.side ? !!ericMoon(v) : false, t = v.anim || 0;
    if (g > 40 || moon) {
      c.save(); c.globalCompositeOperation = 'lighter';
      const k = Math.max(g / 100, moon ? 0.8 : 0);
      glowCircle(c, 0, -60, 70 + 30 * k, `rgba(200,220,255,${0.12 + 0.2 * k})`, 'rgba(120,150,255,0)');
      if (k > 0.7) for (let i = 0; i < 3; i++) { const a = t * 5 + i * 2.1; c.strokeStyle = `rgba(230,240,255,${0.5 * k})`; c.lineWidth = 1.5; c.beginPath(); c.moveTo(Math.cos(a) * 26, -60 + Math.sin(a) * 40); c.lineTo(Math.cos(a) * 34, -70 + Math.sin(a) * 50); c.stroke(); }
      c.restore();
    }
  },
});

const APEPX = PixelArt.make({
  id: 'ape', rig: false, k: 1, win: [-100, -170, 210, 180],
  state(v, t, st) {
    const pose = v.pose, run = pose === 'run' ? Math.sin(t * 8) * 6 : 0;
    const roar = v.roar !== undefined ? v.roar : (pose === 'cast' || pose === 'charge' ? 1 : 0);
    const glow = v.mouthGlow !== undefined ? v.mouthGlow : (pose === 'cast' ? 1 : 0);
    const tb = pose === 'punch' ? [-20, -30] : [-40, -6];
    const fh = pose === 'punch' ? [72, -64] : pose === 'charge' ? [48, -120] : pose === 'jump' ? [42, -100] : [42, -6];
    const fe = pose === 'punch' ? [46, -74] : pose === 'charge' ? [46, -90] : [44, -48];
    // arms ease toward each pose, so the ape swings instead of snapping
    const ez = (k, tg) => (st[k] = st[k] ? [st[k][0] + (tg[0] - st[k][0]) * .5, st[k][1] + (tg[1] - st[k][1]) * .5] : tg.slice());
    const q = a => a.map(x => Math.round(x));
    return { br: Math.round(Math.sin(t * 3) * 3) / 2, run: Math.round(run), tail: Math.round(Math.sin(t * 2) * 6), roar: Math.round(roar * 5) / 5, glow: Math.round(glow * 10) / 10,
      eg: Math.round((v.eyeGlow !== undefined ? v.eyeGlow : 1) * 5) / 5, bh: q(ez('bh', tb)), fh: q(ez('fh', fh)), fe: q(ez('fe', fe)) };
  },
  body(g, P, s) {
    const fur = ['#5b3a22', '#3f281a'], dark = ['#3a2414', '#24160c'], chest = ['#c89968', '#a07a4e'], face = ['#dcb48c', '#b08a68'], b = s.br, run = s.run;
    const bez = (a, c1, c2, e) => { const p = []; for (let i = 0; i <= 8; i++) { const u = i / 8, w = 1 - u; p.push([w ** 3 * a[0] + 3 * w * w * u * c1[0] + 3 * w * u * u * c2[0] + u ** 3 * e[0], w ** 3 * a[1] + 3 * w * w * u * c1[1] + 3 * w * u * u * c2[1] + u ** 3 * e[1]]); } return p; };
    const tp = bez([-28, -40], [-60, -30], [-66 + s.tail, -70], [-48, -86]);
    g.paint(tp.slice(1).map((q, i) => g.cap(tp[i], q, 4)), ...dark);
    const A = [-26, -78 + b];
    g.paint([g.cap(A, [-40, -46], 9), g.cap([-40, -46], s.bh, 9), g.ell(s.bh[0], s.bh[1], 11, 11)], ...dark);
    g.paint([g.ell(-18 + run, -14, 15, 17), g.ell(-16 + run, -1, 14, 5)], ...dark);
    g.paint([g.ell(18 - run, -14, 15, 17)], ...fur); g.paint([g.ell(22 - run, -1, 14, 5)], ...dark);
    g.paint([g.ell(0, -56 + b, 42, 38)], ...fur);
    g.paint([g.ell(8, -54 + b, 25, 27)], ...chest);
    const fr = []; for (let i = 0; i < 7; i++) { const a = -Math.PI * .95 + i * .3; fr.push(g.poly([[Math.cos(a) * 40, -60 + Math.sin(a) * 36 + b], [Math.cos(a) * 50, -60 + Math.sin(a) * 46 + b], [Math.cos(a + .15) * 40, -60 + Math.sin(a + .15) * 36 + b]])); }
    g.paint(fr, ...fur, false);
    const hx = 12, hy = -96 + b;
    const tufts = []; for (let i = 0; i < 5; i++) tufts.push(g.poly([[hx - 16 + i * 7, hy - 14], [hx - 18 + i * 7, hy - 28 - (i % 2) * 5], [hx - 10 + i * 7, hy - 16]]));
    g.paint([g.ell(hx, hy, 21, 21), ...tufts], ...fur);
    g.paint([g.ell(hx + 9, hy + 7, 15, 10 + s.roar * 3), g.ell(hx + 2, hy - 6, 15, 7)], ...face);
    g.paint([g.cap([hx - 8, hy - 11], [hx + 16, hy - 9], 2.5)], ...dark);
    g.fill(g.ell(hx + 1, hy - 5, 2.5, 2.5), '#ff2020'); g.fill(g.ell(hx + 11, hy - 5, 2.5, 2.5), '#ff2020');
    if (s.roar > 0) {
      g.fill(g.ell(hx + 13, hy + 10, 7, 3 + s.roar * 6), '#2a0808');
      g.fill(g.poly([[hx + 7, hy + 5], [hx + 9, hy + 10], [hx + 11, hy + 5]]), '#ffffff'); g.fill(g.poly([[hx + 15, hy + 5], [hx + 17, hy + 10], [hx + 19, hy + 5]]), '#ffffff');
    } else g.line([[hx + 6, hy + 11], [hx + 20, hy + 10]], '#3a2414', 2);
    g.paint([g.cap([26, -78 + b], s.fe, 9.5), g.cap(s.fe, s.fh, 9.5), g.ell(s.fh[0], s.fh[1], 12, 12)], ...fur);
  },
  post(c, v, P, s) {
    const hx = 12, hy = -96 + s.br;
    c.save(); c.globalCompositeOperation = 'lighter';
    glowCircle(c, hx + 1, hy - 5, 9 * s.eg + 1, 'rgba(255,40,40,0.9)'); glowCircle(c, hx + 11, hy - 5, 9 * s.eg + 1, 'rgba(255,40,40,0.9)');
    if (s.glow > 0) { glowCircle(c, hx + 13, hy + 10, 26 * s.glow, 'rgba(255,245,200,1)', 'rgba(255,200,80,0)'); glowCircle(c, hx + 13, hy + 10, 9 * s.glow, 'rgba(255,255,255,1)'); }
    c.restore();
  },
});
const ERICPX_ALL = { draw: (c, v) => (v.transformed ? APEPX.draw(c, v) : ERICPX.draw(c, v)) };

// ---------------- hook them into the roster ----------------
// Settings → PIXEL ART FIGHTERS switches every pixel fighter back to its vector art.
const pixelArtOn = () => !(typeof Save !== 'undefined' && Save.set && Save.set.pixelArt === false);
(() => {
  const set = (id, px, b64, formFx, formB64) => {
    const def = charById(id), oldDraw = def.draw, oldPortrait = def.drawPortrait;
    const pixPortrait = b64 ? PixelArt.portrait(id, b64, oldPortrait, formFx, formB64) : oldPortrait;
    def.draw = (c, v) => pixelArtOn() ? px.draw(c, v) : oldDraw(c, v);
    def.drawPortrait = (c, o, d) => pixelArtOn() ? pixPortrait(c, o, d) : oldPortrait(c, o, d);
  };
  // Aatrox's def already points at his pixel versions; give him his vector ones as the fallback.
  const aat = charById('aatrox');
  aat.draw = (c, v) => pixelArtOn() ? AATPX.draw(c, v) : drawAatrox(c, v);
  aat.drawPortrait = (c, o, d) => pixelArtOn() ? drawAatroxPixelPortrait(c, o, d) : drawAatroxPortraitVector(c, o);
  set('kael', KAELPX, '', PixelArt.formGlow('rgba(255,70,20,0.4)', 'rgba(255,110,40,0.85)'));
  set('seraph', SERPX, '', PixelArt.formGlow('rgba(255,245,210,0.35)', 'rgba(255,250,220,0.9)'));
  set('sion', SIONPX, '', PixelArt.formGlow('rgba(255,90,40,0.3)', 'rgba(255,140,70,0.85)'));
  set('eric', ERICPX_ALL, '', null, '');
  set('volibear', VOLPX, '', null, '');
  set('razor', RAZORPX, '', PixelArt.formGlow('rgba(255,30,30,0.4)', 'rgba(255,80,80,0.85)'));
})();
